-                    horizon_result.pushKV("feerate", ValueFromFeeRate(feeRate, self.Arg<bool>("satvB") ? FeeRateUnit::SAT_VB : FeeRateUnit::BTC_KVB ));
+                    horizon_result.pushKV("feerate", ValueFromFeeRate(feeRate, feerate_units));
